/**
 * libe data model.
 *
 * Conventions
 * - Primary keys are UUIDs generated by Postgres.
 * - `day` columns are calendar dates (`YYYY-MM-DD` strings, no timezone).
 * - Minutes-of-day (`start_min`, `end_min`) are 0‥1440 relative to `day`.
 * - Points in time are `timestamptz`, surfaced as JS `Date`.
 * - The TS property `order` maps to the column `sort_order` (ORDER is an SQL keyword).
 *   Lower values come first; gaps are allowed.
 */
import { relations, sql } from 'drizzle-orm';
import {
	boolean,
	check,
	date,
	index,
	integer,
	pgEnum,
	pgTable,
	real,
	text,
	timestamp,
	uniqueIndex,
	uuid
} from 'drizzle-orm/pg-core';
// Relative (not `#lib/…`): drizzle-kit loads this file outside Vite.
import { QUEST_COLORS } from '../../quest-colors.ts';
import { DAILY_GOAL_MAX, DAILY_GOAL_MIN, DAILY_GOAL_STEP } from '../../daily-goal.ts';

const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();

// ─── Enums ──────────────────────────────────────────────────────────────────

export const taskKind = pgEnum('task_kind', ['quest', 'other']);
export const sessionState = pgEnum('session_state', ['running', 'paused', 'completed']);
export const sessionSource = pgEnum('session_source', ['focus', 'manual', 'pomodoro']);
export const pomodoroPhase = pgEnum('pomodoro_phase', ['focus', 'short_break', 'long_break']);

// ─── Quests ─────────────────────────────────────────────────────────────────

export const quests = pgTable('quests', {
	id: uuid('id').primaryKey().defaultRandom(),
	name: text('name').notNull(),
	description: text('description').notNull().default(''),
	/** A single emoji used as the quest icon. */
	icon: text('icon').notNull().default('✨'),
	/** Key of the quest colour family (see `QUEST_COLORS` in `#lib/quest-colors`). */
	color: text('color').notNull().default('amber'),
	/** Target hours per week; null = no budget. */
	weeklyBudgetH: real('weekly_budget_h'),
	/** Set when the quest is archived/finished. Closed quests are hidden from pickers. */
	closedAt: timestamp('closed_at', { withTimezone: true }),
	order: integer('sort_order').notNull().default(0),
	createdAt: createdAt()
});

// ─── Tasks ──────────────────────────────────────────────────────────────────

export const tasks = pgTable(
	'tasks',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		/** Required for `kind = 'quest'`, must be null for `kind = 'other'`. */
		questId: uuid('quest_id').references(() => quests.id, { onDelete: 'cascade' }),
		kind: taskKind('kind').notNull(),
		title: text('title').notNull(),
		description: text('description').notNull().default(''),
		/** Planned/estimated duration in minutes. */
		durationMin: integer('duration_min'),
		/** Planned day. Null = backlog (not scheduled yet). */
		day: date('day', { mode: 'string' }),
		/** iCalendar RRULE string (e.g. `FREQ=WEEKLY;BYDAY=MO,WE`), null = one-off. */
		recurrenceRule: text('recurrence_rule'),
		doneAt: timestamp('done_at', { withTimezone: true }),
		order: integer('sort_order').notNull().default(0),
		createdAt: createdAt()
	},
	(t) => [
		index('tasks_day_idx').on(t.day),
		index('tasks_quest_idx').on(t.questId),
		check(
			'tasks_kind_quest_chk',
			sql`(${t.kind} = 'quest' AND ${t.questId} IS NOT NULL) OR (${t.kind} = 'other' AND ${t.questId} IS NULL)`
		),
		check('tasks_duration_chk', sql`${t.durationMin} IS NULL OR ${t.durationMin} > 0`)
	]
);

// ─── Blocks (planned time on the timeline) ──────────────────────────────────

export const blocks = pgTable(
	'blocks',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		taskId: uuid('task_id')
			.notNull()
			.references(() => tasks.id, { onDelete: 'cascade' }),
		day: date('day', { mode: 'string' }).notNull(),
		startMin: integer('start_min').notNull(),
		endMin: integer('end_min').notNull(),
		createdAt: createdAt()
	},
	(t) => [
		index('blocks_day_idx').on(t.day),
		check(
			'blocks_range_chk',
			sql`${t.startMin} >= 0 AND ${t.endMin} <= 1440 AND ${t.startMin} < ${t.endMin}`
		)
	]
);

// ─── Sessions (logged time) ─────────────────────────────────────────────────

export const sessions = pgTable(
	'sessions',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		taskId: uuid('task_id')
			.notNull()
			.references(() => tasks.id, { onDelete: 'cascade' }),
		state: sessionState('state').notNull().default('running'),
		startedAt: timestamp('started_at', { withTimezone: true }).notNull().defaultNow(),
		/**
		 * Focus/pomodoro: planned length (countdown target), null = open-ended stopwatch.
		 * Manual logs: the logged length.
		 */
		durationMin: integer('duration_min'),
		/** Sum of all finished pauses in milliseconds. */
		pausedMs: integer('paused_ms').notNull().default(0),
		/** Start of the current pause while `state = 'paused'` (needed for a server-side timer). */
		pausedAt: timestamp('paused_at', { withTimezone: true }),
		endedAt: timestamp('ended_at', { withTimezone: true }),
		source: sessionSource('source').notNull().default('focus'),
		createdAt: createdAt()
	},
	(t) => [
		index('sessions_task_idx').on(t.taskId),
		index('sessions_started_idx').on(t.startedAt),
		check('sessions_paused_chk', sql`${t.pausedMs} >= 0`),
		// At most one active (running/paused) session across the whole app.
		uniqueIndex('sessions_one_active_idx')
			.on(sql`(${t.state} <> 'completed')`)
			.where(sql`${t.state} <> 'completed'`)
	]
);

// ─── Pomodoro (M4) ──────────────────────────────────────────────────────────

/**
 * The active pomodoro run (at most one with `ended_at IS NULL`). Each focus round is a
 * `sessions` row (`source = 'pomodoro'`); breaks are not logged, but the current phase lives
 * here so every client/reload sees the same state. Phase rollover is derived lazily from the
 * timestamps when the timer is read (see `#lib/timer.ts` → `rolloverPomodoro`).
 */
export const pomodoroRuns = pgTable(
	'pomodoro_runs',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		taskId: uuid('task_id')
			.notNull()
			.references(() => tasks.id, { onDelete: 'cascade' }),
		phase: pomodoroPhase('phase').notNull().default('focus'),
		/** 1-based number of the current/last focus round in this run (keeps counting across cycles). */
		round: integer('round').notNull().default(1),
		/** Start of the current phase; null = the phase waits for the user (auto-start off). */
		phaseStartedAt: timestamp('phase_started_at', { withTimezone: true }),
		/** Length of the current phase in minutes (fixed when the phase is entered). */
		phaseMin: integer('phase_min').notNull(),
		endedAt: timestamp('ended_at', { withTimezone: true }),
		createdAt: createdAt()
	},
	(t) => [
		uniqueIndex('pomodoro_runs_one_active_idx')
			.on(sql`(${t.endedAt} IS NULL)`)
			.where(sql`${t.endedAt} IS NULL`),
		check('pomodoro_runs_round_chk', sql`${t.round} >= 1`),
		check('pomodoro_runs_phase_min_chk', sql`${t.phaseMin} > 0`)
	]
);

/**
 * App settings — a single row (`id = 1`): pomodoro intervals (minutes), the UI language and
 * the owner's profile (global, the same on every device — see `#lib/profile.ts`).
 */
export const settings = pgTable(
	'settings',
	{
		id: integer('id').primaryKey().default(1),
		pomodoroFocusMin: integer('pomodoro_focus_min').notNull().default(25),
		pomodoroShortBreakMin: integer('pomodoro_short_break_min').notNull().default(5),
		pomodoroLongBreakMin: integer('pomodoro_long_break_min').notNull().default(15),
		/** A long break follows every N-th focus round. */
		pomodoroLongBreakEvery: integer('pomodoro_long_break_every').notNull().default(4),
		/** Start the next phase automatically when one ends. */
		pomodoroAutoStart: boolean('pomodoro_auto_start').notNull().default(true),
		/** UI language: `auto` (per request from `Accept-Language`), `en` or `de`. */
		language: text('language').notNull().default('auto'),
		/** Profile: the owner's name (null = none set); trimmed, 1–40 code points. */
		displayName: text('display_name'),
		/** Profile: avatar colour, a key of `QUEST_COLORS`. */
		avatarColor: text('avatar_color').notNull().default('amber'),
		/** Profile: a single emoji shown instead of the initials (null = initials). */
		avatarEmoji: text('avatar_emoji'),
		/** Daily goal in minutes (null = no goal): 15–960, a multiple of 15 (`#lib/daily-goal.ts`). */
		dailyGoalMin: integer('daily_goal_min'),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow()
	},
	(t) => [
		check('settings_single_row_chk', sql`${t.id} = 1`),
		check('settings_language_chk', sql`${t.language} in ('auto', 'en', 'de')`),
		check(
			'settings_display_name_chk',
			sql`${t.displayName} IS NULL OR (char_length(${t.displayName}) BETWEEN 1 AND 40 AND ${t.displayName} = btrim(${t.displayName}))`
		),
		// Built from `QUEST_COLORS`: a new colour key shows up as a schema diff (new migration).
		check(
			'settings_avatar_color_chk',
			sql`${t.avatarColor} in (${sql.raw(QUEST_COLORS.map((c) => `'${c}'`).join(', '))})`
		),
		// One grapheme can be several code points (ZWJ sequences, tag flags); the app checks
		// "exactly one emoji" (`isSingleEmoji`), the database only bounds the length.
		check(
			'settings_avatar_emoji_chk',
			sql`${t.avatarEmoji} IS NULL OR (char_length(${t.avatarEmoji}) BETWEEN 1 AND 16 AND ${t.avatarEmoji} = btrim(${t.avatarEmoji}))`
		),
		check(
			'settings_daily_goal_chk',
			sql`${t.dailyGoalMin} IS NULL OR (${t.dailyGoalMin} BETWEEN ${sql.raw(String(DAILY_GOAL_MIN))} AND ${sql.raw(String(DAILY_GOAL_MAX))} AND ${t.dailyGoalMin} % ${sql.raw(String(DAILY_GOAL_STEP))} = 0)`
		)
	]
);

// ─── Devices & pairing (M7) ─────────────────────────────────────────────────

/** How a device talks to libe: a plain browser tab, an installed PWA, or the Tauri shell. */
export const deviceKind = pgEnum('device_kind', ['browser', 'pwa', 'tauri']);

/**
 * Every client (browser, iOS home-screen app, Tauri shell) is a paired device. Its secret
 * token lives only on the device (cookie / OS keychain); the server keeps the SHA-256 hex.
 * Revoked devices keep their row (`revoked_at`) so a stale token can never come back.
 */
export const devices = pgTable(
	'devices',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		/** SHA-256 (hex) of the device token. */
		tokenHash: text('token_hash').notNull().unique(),
		name: text('name').notNull(),
		kind: deviceKind('kind').notNull().default('browser'),
		/** User agent at pairing time (shown as a hint in the device list). */
		userAgent: text('user_agent'),
		pairedAt: timestamp('paired_at', { withTimezone: true }).notNull().defaultNow(),
		/** Throttled to one update per minute. */
		lastSeenAt: timestamp('last_seen_at', { withTimezone: true }),
		/** Last time the `libe_device` cookie was re-issued (sliding expiry, ≤ once a day). */
		cookieRenewedAt: timestamp('cookie_renewed_at', { withTimezone: true }),
		revokedAt: timestamp('revoked_at', { withTimezone: true })
	},
	(t) => [index('devices_active_idx').on(t.revokedAt)]
);

/**
 * Short-lived pairing codes (6 digits, 10 min, single use). Only a SHA-256 of the code is
 * stored. Every wrong guess counts against all codes active at that moment; 5 wrong
 * guesses invalidate a code.
 */
export const pairingCodes = pgTable(
	'pairing_codes',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		codeHash: text('code_hash').notNull(),
		expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
		usedAt: timestamp('used_at', { withTimezone: true }),
		attempts: integer('attempts').notNull().default(0),
		/** The paired device that generated the code. */
		createdByDeviceId: uuid('created_by_device_id').references(() => devices.id, {
			onDelete: 'cascade'
		}),
		/** The device that was paired with this code. */
		deviceId: uuid('device_id').references(() => devices.id, { onDelete: 'set null' }),
		createdAt: createdAt()
	},
	(t) => [index('pairing_codes_hash_idx').on(t.codeHash)]
);

// ─── Relations (for `db.query.*`) ───────────────────────────────────────────

export const questsRelations = relations(quests, ({ many }) => ({ tasks: many(tasks) }));

export const tasksRelations = relations(tasks, ({ one, many }) => ({
	quest: one(quests, { fields: [tasks.questId], references: [quests.id] }),
	blocks: many(blocks),
	sessions: many(sessions)
}));

export const blocksRelations = relations(blocks, ({ one }) => ({
	task: one(tasks, { fields: [blocks.taskId], references: [tasks.id] })
}));

export const pomodoroRunsRelations = relations(pomodoroRuns, ({ one }) => ({
	task: one(tasks, { fields: [pomodoroRuns.taskId], references: [tasks.id] })
}));

export const sessionsRelations = relations(sessions, ({ one }) => ({
	task: one(tasks, { fields: [sessions.taskId], references: [tasks.id] })
}));

// ─── Inferred types ─────────────────────────────────────────────────────────

export type Quest = typeof quests.$inferSelect;
export type NewQuest = typeof quests.$inferInsert;
export type Task = typeof tasks.$inferSelect;
export type NewTask = typeof tasks.$inferInsert;
export type Block = typeof blocks.$inferSelect;
export type NewBlock = typeof blocks.$inferInsert;
export type Session = typeof sessions.$inferSelect;
export type NewSession = typeof sessions.$inferInsert;
export type PomodoroRun = typeof pomodoroRuns.$inferSelect;
export type Settings = typeof settings.$inferSelect;
export type PairingCode = typeof pairingCodes.$inferSelect;
export type Device = typeof devices.$inferSelect;
